INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 20, 'theory', 'Quiz: photo sharing');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 20, 0, 'Why is processing of an uploaded photo asynchronous, through a queue?', '["It is simpler to write the code", "Processing is heavy: the queue smooths out peaks, and workers are idempotent and scale with queue length", "Servers cannot work with images", "To slow down publishing"]', 1, 'The user sees the post right away, while sizes and formats appear within seconds.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 20, 1, 'Why must the CDN hit rate for images be very high?', '["For looks", "Every miss is a request to storage and a fee for outgoing traffic", "Otherwise encryption does not work", "To reduce the number of users"]', 1, 'Immutable addresses let images stay in the CDN for months, and traffic is the main expense.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 20, 2, 'How is the feed built in a photo-sharing service?', '["Pull only", "A hybrid: precomputed feeds in cache for regular authors, celebrity posts mixed in at read time", "Push only", "Randomly"]', 1, 'Fanning out a celebrity post to millions of followers is too expensive.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 20, 3, 'How do you handle thousands of likes per second on a single post?', '["Block likes", "Accumulate counters in fast storage and write them to the database in batches", "Increase the disk size", "Turn off the database"]', 1, 'Deferred writes and aggregation protect a single row from an avalanche of updates.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 20, 4, 'What makes the recommendation ranking service a bottleneck, and how is that mitigated?', '["It is cheap", "Model scoring is expensive (hundreds of requests per second per instance): results are cached and the system degrades to popular content", "It is not needed", "It stores files"]', 1, 'The share of requests going to the model is limited, and under overload non-personalized content is shown.');
